import assert from 'node:assert/strict'
import { readdirSync, readFileSync } from 'node:fs'
import { join, relative, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { lint, readConfig } from 'markdownlint/promise'

// Lints the maintained Markdown with the markdownlint library, called directly. Its command-line
// wrapper exists to expand globs, and its glob stack is the part that carried an unpatched
// advisory. The scope below needs no glob: the root guides, the .github guides, and every guide
// under docs/. RUST_THIRD_PARTY_LICENSES.md is generated by cargo-about. docs/superpowers/ holds
// dated design and decision memos kept as historical records, so it is out of scope here and for
// cspell. The maintained references that happen to live there, such as the publish runbook, are
// linted like every other guide. They are named once, in the cspell.json ignorePaths entry that
// excludes the rest of the directory, and read from it here, so both tools check the same files.
const root = fileURLToPath(new URL('..', import.meta.url))
const GENERATED = new Set(['RUST_THIRD_PARTY_LICENSES.md'])
const HISTORICAL_PREFIX = 'docs/superpowers/'
const maintainedGlob = new RegExp(`^${HISTORICAL_PREFIX}!\\((.+)\\)\\.md$`)
const maintainedStems = JSON.parse(readFileSync(join(root, 'cspell.json'), 'utf8')).ignorePaths
  .map((glob) => maintainedGlob.exec(glob)?.[1])
  .find((stems) => stems !== undefined)
assert.ok(maintainedStems, `cspell.json must exclude ${HISTORICAL_PREFIX} through a !(...) list of its maintained guides`)
const MAINTAINED_HISTORICAL = new Set(maintainedStems.split('|').map((stem) => `${HISTORICAL_PREFIX}${stem}.md`))

function markdownFiles (directory, recursive) {
  return readdirSync(join(root, directory), { recursive, withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
    .map((entry) => relative(root, join(entry.parentPath, entry.name)).split(sep).join('/'))
}

const files = [...markdownFiles('.', false), ...markdownFiles('.github', false), ...markdownFiles('docs', true)]
  .filter((path) => !GENERATED.has(path))
  .filter((path) => !path.startsWith(HISTORICAL_PREFIX) || MAINTAINED_HISTORICAL.has(path))
  .sort()
for (const path of MAINTAINED_HISTORICAL) {
  assert.ok(files.includes(path), `${path} is missing; update the maintained exception in cspell.json`)
}

const config = await readConfig(join(root, '.markdownlint.json'))
const results = await lint({ config, files: files.map((path) => join(root, path)) })
const failures = files.flatMap((path) => results[join(root, path)]
  .toSorted((left, right) => left.lineNumber - right.lineNumber)
  .map((issue) => {
    const detail = issue.errorDetail ?? issue.errorContext
    return `${path}:${issue.lineNumber}: ${issue.ruleNames.join('/')} ${issue.ruleDescription}${detail ? ` [${detail}]` : ''}`
  }))

if (failures.length > 0) {
  console.error(failures.join('\n'))
  process.exit(1)
}

process.stdout.write(`Markdown lint passed for ${files.length} files.\n`)
